window.PROBLEM_SOURCES["swift-11"] = {"id": "swift-11", "language": "swift", "stub": {"path": "swift/practice_problems/problem_11_coverage_tracker.swift", "source": "import Foundation\n\n// Problem 11: Coverage Tracker\n// Swift 6, macOS 14+ | Senior | approximately 45 minutes\n//\n// Track receiver stations, heartbeats, outages, and regional coverage using\n// typed temporal values. You choose the internal data structures; the public\n// interface is the contract. Store mutable state only in this instance.\n// Returned arrays and summaries are immutable snapshots.\n//\n/*\n * Example\n */\n// let tracker = CoverageTracker(now: { Date(timeIntervalSince1970: 1_700_000_300) })\n// try tracker.register(Station(id: \"sta-001\", name: \"North Tower\", region: \"downtown\"))\n// try tracker.recordHeartbeat(for: \"sta-001\", at: Date(timeIntervalSince1970: 1_700_000_000))\n// try tracker.staleStations(after: .seconds(120)) // -> [Station(id: \"sta-001\", ...)]\n// try tracker.coverageStatus(in: \"downtown\", staleAfter: .seconds(120)) // -> .unavailable(...)\n//\n// PART 1 — Stations and heartbeats  (~12 min)\n// Register unique string IDs, accept only strictly increasing heartbeats, and\n// return station snapshots sorted by ID. Calls without `asOf` use injected time.\n//\n// PART 2 — Staleness and outage history  (~16 min)\n// A station is stale when it has no heartbeat or its heartbeat age is greater\n// than the threshold. Allow one open outage per station. Ending an outage must\n// be after its start. Return outage snapshots sorted by start date.\n//\n// PART 3 — Coverage and duration summaries  (~17 min)\n// coverageStatus must compose stations(in:) and staleStations(asOf:after:).\n// outageSummary must compose outages(for:) and count an open outage through\n// the requested/injected time.\n\npublic struct Station: Equatable, Sendable {\n    public let id: String\n    public let name: String\n    public let region: String\n    public init(id: String, name: String, region: String) {\n        self.id = id; self.name = name; self.region = region\n    }\n}\n\npublic struct Outage: Equatable, Sendable {\n    public let stationID: String\n    public let startedAt: Date\n    public let endedAt: Date?\n    public init(stationID: String, startedAt: Date, endedAt: Date? = nil) {\n        self.stationID = stationID; self.startedAt = startedAt; self.endedAt = endedAt\n    }\n}\n\npublic enum CoverageStatus: Equatable, Sendable {\n    case noStations(region: String)\n    case unavailable(region: String, total: Int, stale: Int)\n    case available(region: String, total: Int, healthy: Int, stale: Int)\n}\n\npublic struct OutageSummary: Equatable, Sendable {\n    public let stationID: String\n    public let totalOutages: Int\n    public let hasOpenOutage: Bool\n    public let totalDuration: Duration\n    public init(stationID: String, totalOutages: Int, hasOpenOutage: Bool, totalDuration: Duration) {\n        self.stationID = stationID; self.totalOutages = totalOutages\n        self.hasOpenOutage = hasOpenOutage; self.totalDuration = totalDuration\n    }\n}\n\npublic enum CoverageTrackerError: Error, Equatable, Sendable {\n    case duplicateStation(String)\n    case unknownStation(String)\n    case heartbeatNotIncreasing(stationID: String)\n    case outageAlreadyOpen(stationID: String)\n    case noOpenOutage(stationID: String)\n    case outageEndNotAfterStart(stationID: String)\n    case notImplemented\n}\n\npublic final class CoverageTracker {\n    public init(now: @escaping @Sendable () -> Date) {}\n\n    // MARK: Part 1 — stations and heartbeats\n    public func register(_ station: Station) throws(CoverageTrackerError) { throw .notImplemented }\n    public func recordHeartbeat(for stationID: String, at date: Date) throws(CoverageTrackerError) { throw .notImplemented }\n    public func lastHeartbeat(for stationID: String) throws(CoverageTrackerError) -> Date? { throw .notImplemented }\n    public func stations(in region: String? = nil) -> [Station] { [] }\n\n    // MARK: Part 2 — staleness and outage history\n    public func staleStations(asOf date: Date? = nil, after threshold: Duration) throws(CoverageTrackerError) -> [Station] { throw .notImplemented }\n    public func startOutage(for stationID: String, at date: Date) throws(CoverageTrackerError) { throw .notImplemented }\n    public func endOutage(for stationID: String, at date: Date) throws(CoverageTrackerError) { throw .notImplemented }\n    public func outages(for stationID: String) throws(CoverageTrackerError) -> [Outage] { throw .notImplemented }\n\n    // MARK: Part 3 — coverage and duration summaries\n    public func coverageStatus(in region: String, asOf date: Date? = nil, staleAfter threshold: Duration) throws(CoverageTrackerError) -> CoverageStatus { throw .notImplemented }\n    public func outageSummary(for stationID: String, asOf date: Date? = nil) throws(CoverageTrackerError) -> OutageSummary { throw .notImplemented }\n}\n"}, "test": {"path": "swift/Tests/Problem11CoverageTrackerTests/Problem11CoverageTrackerTests.swift", "source": "import Foundation\nimport Testing\n@testable import Problem11CoverageTracker\n\nprivate let t0 = Date(timeIntervalSince1970: 1_700_000_000)\nprivate let t1 = t0.addingTimeInterval(60)\nprivate let t2 = t0.addingTimeInterval(120)\nprivate let t3 = t0.addingTimeInterval(300)\nprivate let t4 = t0.addingTimeInterval(600)\nprivate func makeFreshTracker(now: Date = t4) -> CoverageTracker { CoverageTracker(now: { now }) }\nprivate func makeSeededTracker(now: Date = t4) throws -> CoverageTracker {\n    let tracker = makeFreshTracker(now: now)\n    try tracker.register(Station(id: \"sta-seed-1\", name: \"North Tower\", region: \"downtown\"))\n    try tracker.register(Station(id: \"sta-seed-2\", name: \"South Tower\", region: \"downtown\"))\n    try tracker.register(Station(id: \"sta-seed-3\", name: \"East Hub\", region: \"eastside\"))\n    try tracker.recordHeartbeat(for: \"sta-seed-1\", at: t0)\n    try tracker.recordHeartbeat(for: \"sta-seed-2\", at: t1)\n    return tracker\n}\n\n@Suite(\"Part 1 — Stations and heartbeats\")\nstruct CoveragePart1 {\n    @Test(\"registration returns sorted snapshots and rejects duplicates\")\n    func registration() throws {\n        let tracker = makeFreshTracker()\n        try tracker.register(Station(id: \"sta-zed\", name: \"Zed\", region: \"north\"))\n        try tracker.register(Station(id: \"sta-alpha\", name: \"Alpha\", region: \"south\"))\n        #expect(tracker.stations().map(\\.id) == [\"sta-alpha\", \"sta-zed\"])\n        #expect(tracker.stations(in: \"north\").map(\\.id) == [\"sta-zed\"])\n        #expect(throws: CoverageTrackerError.duplicateStation(\"sta-zed\")) {\n            try tracker.register(Station(id: \"sta-zed\", name: \"Duplicate\", region: \"north\"))\n        }\n    }\n\n    @Test(\"heartbeats must increase strictly\")\n    func heartbeatOrder() throws {\n        let tracker = try makeSeededTracker()\n        try tracker.recordHeartbeat(for: \"sta-seed-1\", at: t2)\n        #expect(try tracker.lastHeartbeat(for: \"sta-seed-1\") == t2)\n        #expect(try tracker.lastHeartbeat(for: \"sta-seed-3\") == nil)\n        #expect(throws: CoverageTrackerError.heartbeatNotIncreasing(stationID: \"sta-seed-1\")) {\n            try tracker.recordHeartbeat(for: \"sta-seed-1\", at: t2)\n        }\n        #expect(throws: CoverageTrackerError.unknownStation(\"sta-heartbeat-ghost\")) {\n            try tracker.recordHeartbeat(for: \"sta-heartbeat-ghost\", at: t0)\n        }\n    }\n\n    @Test(\"instances own independent state\")\n    func isolation() throws {\n        let first = makeFreshTracker(), second = makeFreshTracker()\n        try first.register(Station(id: \"sta-isolation\", name: \"Only First\", region: \"north\"))\n        #expect(first.stations().count == 1)\n        #expect(second.stations().isEmpty)\n    }\n}\n\n@Suite(\"Part 2 — Staleness and outage history\")\nstruct CoveragePart2 {\n    @Test(\"staleness uses Duration and an exclusive threshold\")\n    func staleness() throws {\n        let tracker = try makeSeededTracker()\n        #expect(try tracker.staleStations(asOf: t2, after: .seconds(120)).map(\\.id) == [\"sta-seed-3\"])\n        #expect(try tracker.staleStations(asOf: t3, after: .seconds(120)).map(\\.id) == [\"sta-seed-1\", \"sta-seed-2\", \"sta-seed-3\"])\n        #expect(try tracker.staleStations(after: .seconds(5)).count == 3)\n    }\n\n    @Test(\"outages open, close, and remain sorted snapshots\")\n    func outageLifecycle() throws {\n        let tracker = makeFreshTracker()\n        try tracker.register(Station(id: \"sta-outage\", name: \"Tower\", region: \"north\"))\n        try tracker.startOutage(for: \"sta-outage\", at: t0)\n        #expect(throws: CoverageTrackerError.outageAlreadyOpen(stationID: \"sta-outage\")) {\n            try tracker.startOutage(for: \"sta-outage\", at: t1)\n        }\n        #expect(throws: CoverageTrackerError.outageEndNotAfterStart(stationID: \"sta-outage\")) {\n            try tracker.endOutage(for: \"sta-outage\", at: t0)\n        }\n        try tracker.endOutage(for: \"sta-outage\", at: t1)\n        try tracker.startOutage(for: \"sta-outage\", at: t2)\n        let snapshot = try tracker.outages(for: \"sta-outage\")\n        try tracker.endOutage(for: \"sta-outage\", at: t3)\n        #expect(snapshot.map(\\.startedAt) == [t0, t2])\n        #expect(snapshot.last?.endedAt == nil)\n        #expect(try tracker.outages(for: \"sta-outage\").last?.endedAt == t3)\n    }\n\n    @Test(\"missing stations and absent open outages are typed failures\")\n    func outageFailures() throws {\n        let tracker = try makeSeededTracker()\n        #expect(throws: CoverageTrackerError.noOpenOutage(stationID: \"sta-seed-1\")) {\n            try tracker.endOutage(for: \"sta-seed-1\", at: t2)\n        }\n        #expect(throws: CoverageTrackerError.unknownStation(\"sta-outage-ghost\")) {\n            try tracker.outages(for: \"sta-outage-ghost\")\n        }\n    }\n}\n\n@Suite(\"Part 3 — Coverage and duration summaries\")\nstruct CoveragePart3 {\n    @Test(\"coverage is represented by associated-value states\")\n    func coverage() throws {\n        let tracker = try makeSeededTracker()\n        #expect(try tracker.coverageStatus(in: \"downtown\", asOf: t2, staleAfter: .seconds(90)) == .available(region: \"downtown\", total: 2, healthy: 1, stale: 1))\n        #expect(try tracker.coverageStatus(in: \"downtown\", asOf: t4, staleAfter: .seconds(30)) == .unavailable(region: \"downtown\", total: 2, stale: 2))\n        #expect(try tracker.coverageStatus(in: \"ghost-region\", asOf: t0, staleAfter: .seconds(60)) == .noStations(region: \"ghost-region\"))\n    }\n\n    @Test(\"outage summaries accumulate closed and injected-time durations\")\n    func summaries() throws {\n        let tracker = makeFreshTracker(now: t4)\n        try tracker.register(Station(id: \"sta-summary\", name: \"Tower\", region: \"north\"))\n        try tracker.startOutage(for: \"sta-summary\", at: t0)\n        try tracker.endOutage(for: \"sta-summary\", at: t1)\n        try tracker.startOutage(for: \"sta-summary\", at: t2)\n        let summary = try tracker.outageSummary(for: \"sta-summary\")\n        #expect(summary.totalOutages == 2)\n        #expect(summary.hasOpenOutage)\n        #expect(summary.totalDuration == .seconds(540))\n    }\n}\n"}, "parts": [{"part": 1, "source": "// PART 1 — Stations and heartbeats  (~12 min)\n// Register unique string IDs, accept only strictly increasing heartbeats, and\n// return station snapshots sorted by ID. Calls without `asOf` use injected time.\n//\n//\n"}, {"part": 2, "source": "// PART 2 — Staleness and outage history  (~16 min)\n// A station is stale when it has no heartbeat or its heartbeat age is greater\n// than the threshold. Allow one open outage per station. Ending an outage must\n// be after its start. Return outage snapshots sorted by start date.\n//\n//\n"}, {"part": 3, "source": "// PART 3 — Coverage and duration summaries  (~17 min)\n// coverageStatus must compose stations(in:) and staleStations(asOf:after:).\n// outageSummary must compose outages(for:) and count an open outage through\n// the requested/injected time.\n\npublic struct Station: Equatable, Sendable {\n    public let id: String\n    public let name: String\n    public let region: String\n    public init(id: String, name: String, region: String) {\n        self.id = id; self.name = name; self.region = region\n    }\n}\n\npublic struct Outage: Equatable, Sendable {\n    public let stationID: String\n    public let startedAt: Date\n    public let endedAt: Date?\n    public init(stationID: String, startedAt: Date, endedAt: Date? = nil) {\n        self.stationID = stationID; self.startedAt = startedAt; self.endedAt = endedAt\n    }\n}\n\npublic enum CoverageStatus: Equatable, Sendable {\n    case noStations(region: String)\n    case unavailable(region: String, total: Int, stale: Int)\n    case available(region: String, total: Int, healthy: Int, stale: Int)\n}\n\npublic struct OutageSummary: Equatable, Sendable {\n    public let stationID: String\n    public let totalOutages: Int\n    public let hasOpenOutage: Bool\n    public let totalDuration: Duration\n    public init(stationID: String, totalOutages: Int, hasOpenOutage: Bool, totalDuration: Duration) {\n        self.stationID = stationID; self.totalOutages = totalOutages\n        self.hasOpenOutage = hasOpenOutage; self.totalDuration = totalDuration\n    }\n}\n\npublic enum CoverageTrackerError: Error, Equatable, Sendable {\n    case duplicateStation(String)\n    case unknownStation(String)\n    case heartbeatNotIncreasing(stationID: String)\n    case outageAlreadyOpen(stationID: String)\n    case noOpenOutage(stationID: String)\n    case outageEndNotAfterStart(stationID: String)\n    case notImplemented\n}\n\npublic final class CoverageTracker {\n    public init(now: @escaping @Sendable () -> Date) {}\n\n    // MARK: Part 1 — stations and heartbeats\n    public func register(_ station: Station) throws(CoverageTrackerError) { throw .notImplemented }\n    public func recordHeartbeat(for stationID: String, at date: Date) throws(CoverageTrackerError) { throw .notImplemented }\n    public func lastHeartbeat(for stationID: String) throws(CoverageTrackerError) -> Date? { throw .notImplemented }\n    public func stations(in region: String? = nil) -> [Station] { [] }\n\n    // MARK: Part 2 — staleness and outage history\n    public func staleStations(asOf date: Date? = nil, after threshold: Duration) throws(CoverageTrackerError) -> [Station] { throw .notImplemented }\n    public func startOutage(for stationID: String, at date: Date) throws(CoverageTrackerError) { throw .notImplemented }\n    public func endOutage(for stationID: String, at date: Date) throws(CoverageTrackerError) { throw .notImplemented }\n    public func outages(for stationID: String) throws(CoverageTrackerError) -> [Outage] { throw .notImplemented }\n\n    // MARK: Part 3 — coverage and duration summaries\n    public func coverageStatus(in region: String, asOf date: Date? = nil, staleAfter threshold: Duration) throws(CoverageTrackerError) -> CoverageStatus { throw .notImplemented }\n    public func outageSummary(for stationID: String, asOf date: Date? = nil) throws(CoverageTrackerError) -> OutageSummary { throw .notImplemented }\n}\n"}], "implementationSurface": "    public func coverageStatus(in region: String, asOf date: Date? = nil, staleAfter threshold: Duration) throws(CoverageTrackerError) -> CoverageStatus { throw .notImplemented }\n    public func outageSummary(for stationID: String, asOf date: Date? = nil) throws(CoverageTrackerError) -> OutageSummary { throw .notImplemented }\n}\n"};
